const SELF_HEAD=new Set(["hook_clean", "headline_stack", "flash_quote", "quote_panel", "ticker_wall", "compare_swipe", "matrix", "salary_stack", "salary_steps", "metric_grid", "stat_tiles", "ladder", "podium", "ring_trio", "radar", "checklist", "dossier", "process_flow", "matchup"]);
function creativeScene(c,s,d,p,t,idx,thumb,id){
 const w=d.w,h=d.h,cx=w/2,cy=h/2,unit=Math.min(w,h),q=t*Math.PI*2;
 const rng=n=>{let z=Math.sin(n*127.1+idx*71.3)*43758.5453;return z-Math.floor(z)};
 const stroke=(color,width=3)=>{c.strokeStyle=color;c.lineWidth=width;c.lineCap='round'};
 const arc=(x,y,r,a,b,col,width=4)=>{c.beginPath();c.arc(x,y,r,a,b);stroke(col,width);c.stroke()};
 const box=(key,x,y,bw,bh,size,color=p.text,options={})=>textBox(c,s,key,{x,y,w:bw,h:bh},size,color,{index:idx,thumbnail:thumb,...options});
 const mix=(a,b,v)=>a+(b-a)*v;
 const k=enter(t,.03,.7),v=1-Math.pow(1-k,2);
 c.save();
 if(id==='neon_ribbon'||id==='liquid_wave'||id==='morphing_blob'||id==='prism_light'){
  for(let j=0;j<7;j++){c.beginPath();for(let i=0;i<=100;i++){let x=i*w/100,y=cy+Math.sin(i*.075+q+j*.64)*unit*(.10+j*.014)+Math.cos(i*.045-q*.7)*unit*.045+(j-3)*unit*.048;if(i===0)c.moveTo(x,y);else c.lineTo(x,y)}stroke(j%2?p.alt:p.main,5+j*1.8);c.globalAlpha=.12+j*.025;c.stroke()}c.globalAlpha=1;
 }else if(id==='glass_orbit'||id==='orbiting_labels'||id==='radial_count'||id==='countdown_arc'){
  for(let j=0;j<8;j++){let r=unit*(.16+j*.038),start=q*(j%2?1:-1)+j*.6;arc(cx,cy,r,start,start+Math.PI*(.55+j*.055),j%2?p.alt:p.main,3+j%3)}
  for(let j=0;j<9;j++){let a=q+j*Math.PI*2/9,r=unit*.32; c.beginPath();c.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,4+j%3,0,7);c.fillStyle=p.hot;c.fill()}
 }else if(id==='particle_burst'||id==='confetti'||id==='starlight'){
  for(let j=0;j<170;j++){let a=rng(j)*Math.PI*2,r=unit*(.03+rng(j+800)*.65)*(.3+.7*v),x=cx+Math.cos(a+q*.12)*r,y=cy+Math.sin(a+q*.12)*r;c.fillStyle=j%3?p.alt:p.main;c.globalAlpha=.25+.7*rng(j+100);c.fillRect(x,y,2+rng(j+7)*6,2+rng(j+9)*6)}c.globalAlpha=1;
 }else if(id==='tunnel_zoom'||id==='neon_frame'||id==='shimmer_grid'){
  for(let j=0;j<15;j++){let r=(j+t*2)%15/15,ww=w*(.12+r*1.25),hh=h*(.12+r*1.25);c.strokeStyle=j%2?p.alt:p.main;c.globalAlpha=.08+.36*(1-r);c.lineWidth=2+(1-r)*3;c.strokeRect(cx-ww/2,cy-hh/2,ww,hh)}c.globalAlpha=1;
 }else if(id==='split_reveal'||id==='cinema_wipe'){
  for(let j=0;j<9;j++){c.save();c.translate(cx,cy);c.rotate(-.28);c.fillStyle=j%2?p.main:p.alt;c.globalAlpha=.10+j*.025;let xx=-w*.8+(j/8)*w*1.6+Math.sin(q+j)*w*.07;c.fillRect(xx,-h,unit*.075,h*2);c.restore()}c.globalAlpha=1;
 }else if(id==='spotlight_stage'){
  for(let j=0;j<6;j++){let a=Math.sin(q+j)*.6+(j-3)*.23;c.save();c.translate(cx,0);c.rotate(a);let g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,p.main+'88');g.addColorStop(1,p.main+'00');c.fillStyle=g;c.beginPath();c.moveTo(0,0);c.lineTo(-unit*.14,h);c.lineTo(unit*.14,h);c.fill();c.restore()}
 }else if(id==='equalizer'||id==='data_columns'||id==='sparkline'){
  let n=26,bw=w*.78/n;for(let j=0;j<n;j++){let val=.12+.7*Math.abs(Math.sin(j*.45+q*1.8)*Math.cos(j*.17-q));let bh=h*.42*val*v; c.fillStyle=j%4?p.alt:p.main;c.globalAlpha=.35+.55*val;c.fillRect(w*.11+j*bw,cy+unit*.24-bh,bw*.62,bh)}c.globalAlpha=1;
 }else if(id==='floating_cards'){
  for(let j=0;j<7;j++){let xx=w*(.08+(j%4)*.22),yy=h*(.19+Math.floor(j/4)*.42)+Math.sin(q+j)*unit*.045;c.fillStyle=p.panel;c.strokeStyle=p.alt;c.lineWidth=2;c.beginPath();c.roundRect(xx,yy,w*.18,h*.20,18);c.fill();c.stroke();arc(xx+w*.09,yy+h*.10,unit*.025,0,Math.PI*2,p.main,5)}
 }else if(id==='ticker_motion'){
  for(let j=0;j<6;j++){let yy=h*(.15+j*.14),xx=(j%2?-1:1)*t*w*.5;c.save();c.translate(xx,0);c.fillStyle=j%2?p.main:p.alt;c.globalAlpha=.18;c.fillRect(-w,yy,w*3,h*.07);c.restore()}c.globalAlpha=1;
 }else if(id==='number_flip'||id==='pulse_typography'){
  for(let j=0;j<8;j++){let r=unit*(.1+j*.048)+Math.sin(q*2+j)*unit*.012;arc(cx,cy,r,0,Math.PI*2,j%2?p.main:p.alt,1.5)}
 }
 c.save();c.translate(cx,cy);let scale=id==='pulse_typography'?1+Math.sin(q)*.045:1;c.scale(scale,scale);c.translate(-cx,-cy);
 box('tag',w*.13,h*.18,w*.74,h*.065,Math.min(30,unit*.028),p.main,{align:'center'});
 box('title',w*.09,h*.28,w*.82,h*.23,Math.min(100,unit*.085),p.text,{align:'center',vertical:'center',lines:3});
 box('value',w*.12,h*.53,w*.76,h*.15,Math.min(92,unit*.078),p.alt,{align:'center',vertical:'center'});
 box('note',w*.14,h*.77,w*.72,h*.10,Math.min(29,unit*.028),p.muted,{align:'center',vertical:'center',lines:2});c.restore();c.restore();
}
/* V11 — cinematic editorial direction for the two uploaded video layouts.
   Larger Kannada-safe title regions; numbers are EXACT excerpts from source text. */
function v11FocusText(source,maxWords=8,maxChars=92){
  const original=String(source??'').replace(/\s+/g,' ').trim();
  const words=original.split(' ');let line=words.length>maxWords?words.slice(0,maxWords).join(' '):original;
  if(line.length>maxChars)line=line.slice(0,maxChars).replace(/\s+\S*$/,'');
  return line!==original?line.replace(/[\s,.…-]+$/,'')+'…':line;
}
function v11Metric(source){
  const text=String(source??'');
  const all=[...text.matchAll(/(?:[₹$€£]\s*)?(?:\d{1,3}(?:,\d{2,3})+|\d+(?:\.\d+)?|[೦-೯]+)(?:\s*(?:ಕೋಟಿ|ಲಕ್ಷ|ಶೇಕಡಾ|%|crore|lakh|million|billion))?/gi)].map(m=>m[0].trim());
  return all.find(x=>/[₹$€£%]|ಕೋಟಿ|ಲಕ್ಷ|crore|lakh|million|billion/i.test(x))||all.find(x=>!/^(?:19|20)\d\d$/.test(x))||'';
}
function v11Editorial(c,s,d,p,t,idx,thumb,id){
  const w=d.w,h=d.h,wide=w>h*1.3,k=enter(t,.045,.35),q=t*Math.PI*2,lead=wide?w*.075:w*.08;
  const original=String(s.title||''),source=[original,s.description].filter(Boolean).join(' ');
  const kannada=/[\u0c80-\u0cff]/.test(source);
  let compact=v11FocusText(original,wide?(kannada?7:9):6,wide?90:65);
  const secondary=String(s.description||'').trim()||original;
  const subtitle=v11FocusText(secondary,wide?17:12,wide?150:115);
  const primaryMetric=v11Metric(source);
  if(id==='quote_panel'&&primaryMetric&&original.includes(primaryMetric)){const pre=original.slice(0,original.indexOf(primaryMetric)).trim();if(pre.length>=12)compact=v11FocusText(pre,wide?9:7,wide?95:69);}
  // Long-form text stays editable in the properties panel; the canvas deliberately shows a concise excerpt.
  const ui={...s,title:compact,description:subtitle};
  const txt=(key,x,y,bw,bh,size,col,options={})=>textBox(c,ui,key,{x,y,w:bw,h:bh},size,col,{index:idx,thumbnail:thumb,...options});
  c.save();
  const acc=id==='hook_clean'?p.main:p.alt;
  // Moving vertical glow and cinematic grid lines, low density so it doesn't overwhelm captions.
  glow(c,w*(id==='hook_clean'?.82:.24)+Math.sin(q)*w*.025,h*.49,Math.min(w,h)*.69,acc,.17);
  c.save();c.globalAlpha=.17;for(let j=0;j<11;j++){
    const x=w*.08+j*w*.082+Math.sin(q+j*.8)*w*.002;
    line(c,x,h*.13,x,h*.85,p.muted,.7);
  }c.restore();
  for(let j=0;j<36;j++){
    const x=(j*157.31+w*.035*Math.sin(q*.5+j))%w,y=(j*173.27+h*.025*Math.cos(q+j))%h;
    c.save();c.globalAlpha=.11+Math.abs(Math.sin(q+j))*.25;dot(c,x,y,j%6===0?3:1.2,j%3?acc:p.alt);c.restore();
  }
  // Timed underline draws from left to right. Distinct from a simple opacity fade.
  const x0=lead,y0=id==='hook_clean'?h*.18:h*.15;
  line(c,x0,y0,x0+(wide?w*.35:w*.57)*enter(t,.02,.45),y0,acc,7);
  if(id==='hook_clean'){
    const bandW=wide?w*.57:w*.84;
    fade(c,enter(t,.01,.23),()=>txt('tag',x0,y0+27,bandW,45,wide?24:23,acc,{weight:900,lines:1}));
    // Camera-like micro parallax with measured breathing, not a static card.
    c.save();c.translate(0,(1-k)*38+Math.sin(q)*3);
    txt('title',x0,h*(wide?.31:.25),bandW,wide?h*.34:h*.32,wide?(kannada?84:106):66,p.text,{weight:900,lines:3});
    c.restore();
    if(s.description)fade(c,enter(t,.27,.60),()=>txt('description',x0,h*(wide?.71:.57),bandW,wide?h*.14:h*.14,wide?29:27,p.muted,{weight:650,lines:3}));
    const cx=wide?w*.81:w*.52,cy=wide?h*.51:h*.79,rad=Math.min(w*.155,h*.28);
    for(let j=0;j<5;j++){
      const radius=rad*(.59+j*.13),start=q*(j%2?1:-1)*.5+j*.8;
      c.save();c.strokeStyle=rgba(j%2?p.alt:acc,.17+j*.05);c.lineWidth=j===3?8:3;c.lineCap='round';
      c.beginPath();c.arc(cx,cy,radius,start,start+Math.PI*(.67+j*.095));c.stroke();c.restore();
    }
    c.save();c.translate(cx,cy);c.rotate(q*.17);line(c,-rad*.85,0,rad*.85,0,rgba(acc,.32),2);line(c,0,-rad*.85,0,rad*.85,rgba(acc,.18),2);c.restore();
    if(primaryMetric){
      const text=primaryMetric.length>20?v11FocusText(primaryMetric,4,20):primaryMetric;
      fade(c,enter(t,.27,.65),()=>{
        let b={x:cx-rad*.99,y:cy-rad*.45,w:rad*1.98,h:rad*.9};
        rr(c,b.x,b.y,b.w,b.h,Math.min(26,rad*.18),rgba(p.bg,.84),rgba(acc,.48),3);
        const metric={...ui,heroFigure:text};textBox(c,metric,'heroFigure',{x:b.x+15,y:b.y+rad*.13,w:b.w-30,h:b.h-rad*.26},wide?77:65,acc,{index:idx,thumbnail:thumb,align:'center',vertical:'center',lines:2,weight:950});
      });
    }
  }else{
    // Quote Panel is now a dramatic editorial spread, not another thin card.
    const left=wide?w*.085:w*.08,titleW=wide?w*.56:w*.84;
    const barStart=h*.24;
    rr(c,left-22,barStart,9,h*(wide?.40:.36)*enter(t,.06,.47),5,acc);
    fade(c,enter(t,.08,.29),()=>txt('tag',left+17,h*.17,titleW,45,24,acc,{weight:900,lines:1}));
    c.save();c.translate((1-k)*(-48),0);
    txt('title',left+17,h*(wide?.30:.27),titleW,wide?h*.36:h*.27,wide?(kannada?80:94):63,p.text,{weight:900,lines:4});
    c.restore();
    if(s.description)fade(c,enter(t,.29,.64),()=>txt('description',left+17,h*(wide?.73:.57),titleW,wide?h*.12:h*.12,wide?29:25,p.muted,{weight:620,lines:3}));
    const cx=wide?w*.818:w*.52,cy=wide?h*.52:h*.79,rad=wide?w*.134:w*.30;
    // Animated staggered quote brackets and light ribbons.
    for(let j=0;j<4;j++){
      const a=(j*.9+q*.31),r=rad*(.76+j*.13);
      c.save();c.strokeStyle=rgba(j%2?acc:p.main,.18+j*.10);c.lineWidth=5+j*1.5;c.lineCap='round';c.beginPath();c.arc(cx,cy,r,a,a+Math.PI*.44);c.stroke();c.restore();
    }
    if(primaryMetric){
      fade(c,enter(t,.25,.68),()=>{
        rr(c,cx-rad*1.05,cy-rad*.62,rad*2.10,rad*1.24,24,rgba(p.bg,.80),rgba(acc,.52),2);
        const metric={...ui,heroFigure:primaryMetric};
        textBox(c,metric,'heroFigure',{x:cx-rad*.95,y:cy-rad*.4,w:rad*1.9,h:rad*.8},wide?93:70,acc,{index:idx,thumbnail:thumb,align:'center',vertical:'center',lines:2,weight:900});
      });
    }else{
      plain(c,'“',cx,cy+rad*.52,wide?250:210,rgba(acc,.35),'center',900);
    }
  }
  c.restore();
}
function renderScene(c,idx,time,canvasObj=cv,{thumb=false,forceRatio=null,transparent=false}={}){const ratio=forceRatio||state.ratio;const d=dim(ratio);c.setTransform(canvasObj.width/d.w,0,0,canvasObj.height/d.h,0,0);c.clearRect(0,0,d.w,d.h);const p=T(),s=state.data[idx],id=SCENES[idx].id,tt=clamp(time*state.speed);if(!thumb){activeBoxes=[];lastFit=0;warnings=[]}c.save();if(!transparent)baseBackground(c,d.w,d.h,tt,p,thumb);chrome(c,d.w,d.h,tt,p,SCENES[idx].category,thumb);if(!SELF_HEAD.has(id))head(c,s,d,p,idx,thumb);if(CREATIVE_IDS.has(id))creativeScene(c,s,d,p,tt,idx,thumb,id);else if(MEGA_IDS.has(id))megaScene(c,s,d,p,tt,idx,thumb,id);else if(id==='hook_clean'||id==='quote_panel')v11Editorial(c,s,d,p,tt,idx,thumb,id);else content(c,s,d,p,tt,idx,thumb,id);if(state.safe&&!thumb){const x=d.w*.06,y=d.h*.06;c.strokeStyle=rgba(p.hot,.65);c.lineWidth=2;c.setLineDash([8,7]);c.strokeRect(x,y,d.w-2*x,d.h-2*y);c.setLineDash([])}c.restore();if(!thumb){const stat=$('fitStatus');stat.textContent=lastFit?'Auto-fit ON · '+lastFit+' text area(s) adjusted':'Auto-fit ON · Safe layout';stat.style.color=lastFit?'#f8cb7e':'#b8dc85'}}
/* Editor controls, interactive positioning and exports */
function info(t){$('status').textContent=t}
function renderThumb(i){const ele=$('thumb-'+i);if(!ele)return;let temp=document.createElement('canvas');temp.width=250;temp.height=141;try{renderScene(temp.getContext('2d'),i,.84,temp,{thumb:true,forceRatio:'landscape'});ele.src=temp.toDataURL('image/jpeg',.76)}catch(e){console.warn('Preview '+i+' failed',e)}}
function sceneList(){const el=$('sceneList'),q=state.search.trim().toLowerCase();v8Observer?.disconnect();el.replaceChildren();let shown=0;SCENES.forEach((s,i)=>{if(state.category!=='ALL'&&state.category!==s.category)return;if(q&&!(`${s.name} ${s.desc} ${s.category}`.toLowerCase().includes(q)))return;shown++;const btn=document.createElement('button');btn.className='scenebtn'+(i===state.scene?' active':'');btn.type='button';btn.title=s.desc;const img=document.createElement('img');img.id='thumb-'+i;img.alt=s.name;const lab=document.createElement('span');const title=document.createElement('strong');title.textContent=s.name;const note=document.createElement('small');note.textContent=s.category+' · '+s.seconds+'s';lab.append(title,note);btn.append(img,lab);btn.onclick=()=>setScene(i);el.append(btn);lazySceneThumb(i)});$('totalScenes').textContent=shown+' / '+SCENES.length+' layouts';if(!shown){let e=document.createElement('div');e.className='empty';e.textContent='No matching layouts';el.append(e)}}
function categories(){const items=['ALL',...new Set(SCENES.map(x=>x.category))],wrap=$('categoryTabs');wrap.replaceChildren();for(const cat of items){const btn=document.createElement('button');btn.textContent=cat==='ALL'?'All':cat.slice(0,1)+cat.slice(1).toLowerCase();btn.className=state.category===cat?'active':'';btn.onclick=()=>{state.category=cat;categories();sceneList()};wrap.append(btn)}}
function textSelect(key){state.selected=key;const inp=$('selectedField');if(inp)inp.value=key;updateTextPanel();renderFrame()}
function contentFields(){const el=$('contentFields');el.replaceChildren();const s=scene();s.fields.forEach(f=>{const group=document.createElement('div');group.className='controlgroup';let row=document.createElement('div');row.className='fieldlabel';let label=document.createElement('label');label.textContent=f.label;label.htmlFor='fld-'+f.key;let btn=document.createElement('button');btn.textContent='Adjust type ↗';btn.type='button';btn.onclick=()=>{textSelect(f.key);setTab('style')};row.append(label,btn);let input=f.kind==='route'||f.kind==='series'||f.value.length>95?document.createElement('textarea'):document.createElement('input');if(input.tagName==='INPUT')input.type='text';else input.rows=f.kind==='route'?5:f.kind==='series'?2:3;input.id='fld-'+f.key;input.className='control';input.value=D()[f.key];input.onfocus=()=>{state.selected=f.key;updateTextPanel()};input.oninput=()=>{D()[f.key]=input.value;v8SyncQuick(f.key,input.value);renderFrame();renderThumb(state.scene)};group.append(row,input);if(f.kind==='route'){const help=document.createElement('div');help.className='fieldmeta';help.textContent='Name | Latitude | Longitude | Figure — one stop per line';group.append(help)}el.append(group)});const inp=$('selectedField');inp.replaceChildren();s.fields.filter(f=>f.kind!=='route'&&f.kind!=='series').forEach(f=>{let o=document.createElement('option');o.value=f.key;o.textContent=f.label;inp.append(o)});if(!s.fields.some(f=>f.key===state.selected&&f.kind!=='route'&&f.kind!=='series'))state.selected='title';inp.value=state.selected;updateTextPanel()}
function setTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.insptab').forEach(x=>x.classList.toggle('active',x.id==='tab-'+tab))}
function colorPicker(){const pal=$('palettes');pal.replaceChildren();THEMES.forEach(t=>{let btn=document.createElement('button');btn.type='button';btn.className='palettebtn'+(state.theme===t.id&&!state.colors?' active':'');btn.title=t.name;btn.style.background=`linear-gradient(135deg,${t.bg} 42%,${t.main} 42% 73%,${t.alt} 73%)`;btn.onclick=()=>{state.theme=t.id;state.colors=null;colorPicker();colorControls();sceneList();renderFrame()};pal.append(btn)});colorControls()}
function colorControls(){const el=$('colorInputs');el.replaceChildren();let p=T();for(const [k,name] of [['bg','Background base'],['panel','Card surface'],['main','Primary accent'],['alt','Secondary accent'],['hot','Warning accent'],['text','Primary text'],['muted','Muted text']]){let row=document.createElement('label');row.className='colorrow';let span=document.createElement('span');span.textContent=name;let inp=document.createElement('input');inp.type='color';inp.value=p[k];inp.oninput=()=>{if(!state.colors)state.colors={...T()};state.colors[k]=inp.value;document.querySelectorAll('.palettebtn').forEach(b=>b.classList.remove('active'));renderFrame();renderThumb(state.scene)};row.append(span,inp);el.append(row)}}
function getTextStyle(){if(!state.typo[state.scene][state.selected])state.typo[state.scene][state.selected]={size:100,x:0,y:0,color:''};return state.typo[state.scene][state.selected]}
