function setScene(i){if(!Number.isInteger(i)||i<0||i>=SCENES.length)return;state.scene=i;const s=scene();$('sceneCategory').textContent=s.category+' / TEMPLATE '+String(i+1).padStart(2,'0');$('sceneTitle').textContent=s.name;$('sceneDesc').textContent=s.desc;selectSceneFields();document.querySelectorAll('.scenebtn').forEach(b=>b.classList.remove('active'));sceneList();state.t=0;state.start=performance.now();state.playing=true;$('playPause').textContent='Ⅱ';renderFrame()}
function setRatio(ratio){if(!['landscape','portrait','square'].includes(ratio))return;state.ratio=ratio;const sizes={landscape:[1920,1080],portrait:[1080,1920],square:[1080,1080]};[cv.width,cv.height]=sizes[ratio];cv.style.aspectRatio=ratio==='landscape'?'16 / 9':ratio==='portrait'?'9 / 16':'1 / 1';$('resolution').textContent=cv.width+' × '+cv.height;document.querySelectorAll('[data-ratio]').forEach(b=>b.classList.toggle('active',b.dataset.ratio===ratio));renderFrame()}
function renderFrame(){renderScene(ctx,state.scene,state.t,cv)}
function resetClock(t=0){state.t=t;state.start=performance.now()-t*1000*state.durations[state.scene];renderFrame()}
function ticker(timestamp){if(state.playing&&!state.recording){let duration=state.durations[state.scene],elapsed=(timestamp-state.start)/1000;state.t=((elapsed%duration)+duration)%duration/duration;renderFrame()}const sec=state.t*state.durations[state.scene];$('scrub').value=Math.round(state.t*1000);$('currentTime').textContent='00:'+sec.toFixed(1).padStart(4,'0');$('totalTime').textContent='00:'+state.durations[state.scene].toFixed(1).padStart(4,'0');requestAnimationFrame(ticker)}
function fromPointer(ev){const rect=cv.getBoundingClientRect(),d=dim();return{x:(ev.clientX-rect.left)/rect.width*d.w,y:(ev.clientY-rect.top)/rect.height*d.h}}
function overlap(a,b){const x=Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)),y=Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));return x*y>40}
function pointerEvents(){cv.addEventListener('pointerdown',e=>{if(state.recording)return;const pos=fromPointer(e);const boxes=[...activeBoxes].reverse();const hit=boxes.find(b=>pos.x>=b.x&&pos.x<=b.x+b.w&&pos.y>=b.y&&pos.y<=b.y+b.h);if(!hit)return;let st=state.typo[state.scene][hit.key]||{x:0,y:0,size:100};drag={key:hit.key,startX:pos.x,startY:pos.y,origX:st.x||0,origY:st.y||0};textSelect(hit.key);cv.setPointerCapture(e.pointerId);e.preventDefault()});cv.addEventListener('pointermove',e=>{if(!drag)return;let a=fromPointer(e),d=dim(),styles=getTextStyle();let dx=Math.round(drag.origX+a.x-drag.startX),dy=Math.round(drag.origY+a.y-drag.startY);const target=activeBoxes.find(b=>b.key===drag.key);if(!target)return;const rx=target.x+(dx-(styles.x||0)),ry=target.y+(dy-(styles.y||0)),rect={x:rx,y:ry,w:target.w,h:target.h};const safe=rect.x>=12&&rect.y>=98&&rect.x+rect.w<=d.w-12&&rect.y+rect.h<=d.h-62;const collision=activeBoxes.some(b=>b.key!==drag.key&&overlap(rect,b));if(!safe||collision){info(collision?'Position blocked: overlaps another editable text area':'Position blocked: outside canvas-safe area');return}styles.x=dx;styles.y=dy;$('textX').value=dx;$('textY').value=dy;renderFrame()});const end=()=>{if(drag){drag=null;renderThumb(state.scene)}};cv.addEventListener('pointerup',end);cv.addEventListener('pointercancel',end)}
function fileName(ext){return 'MotionUltra_V9_'+String(state.scene+1).padStart(2,'0')+'_'+scene().id+'_'+(state.ratio==='portrait'?'9x16':state.ratio==='square'?'1x1':'16x9')+'.'+ext}
