async function exportVideo(){if(state.recording)return;if(!cv.captureStream||!window.MediaRecorder){info('Video export requires Chrome or Edge.');return}const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime){info('No supported WebM recorder found');return}state.playing=false;state.recording=true;$('exportVideo').disabled=true;resetClock(0);const fps=Number($('fps').value)||30,stream=cv.captureStream(fps),chunks=[];let recorder;try{recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:fps===60?18000000:12000000})}catch(e){state.recording=false;$('exportVideo').disabled=false;info('Recording failed: '+e.message);return}recorder.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(x=>x.stop());state.recording=false;$('exportVideo').disabled=false;if(chunks.length){const blob=new Blob(chunks,{type:mime});download(blob,fileName('webm'));info('Animation exported · '+(blob.size/1048576).toFixed(1)+' MB')}else info('No video data produced');resetClock(0)};recorder.start(100);info('Recording animation in real time…');const started=performance.now(),duration=state.durations[state.scene]*1000;let stopped=false;function captureFrame(now){if(!state.recording||stopped)return;state.t=clamp((now-started)/duration);renderFrame();if(now-started>=duration){stopped=true;if(recorder.state==='recording')recorder.stop()}else requestAnimationFrame(captureFrame)}requestAnimationFrame(captureFrame)}
