for(const sc of V8_LAYOUTS){SCENES.push(sc);state.data.push(Object.fromEntries(sc.fields.map(f=>[f.key,f.value])));state.typo.push({});state.durations.push(sc.seconds);state.bgStyles.push(null)}
const V8_IDS=new Set(V8_LAYOUTS.map(s=>s.id));
state.motionPreset='cinematic';state.textMotion='rise';state.atmosphere='none';state.fxStrength=65;state.metricAnimation=true;
const v8S=(a,b,t)=>a+(b-a)*t;
const v8N=(seed)=>{const v=Math.sin(seed*34.697+17.37)*43758.5453123;return v-Math.floor(v)};
const v8Point=(c,x,y,r,color)=>{c.beginPath();c.arc(x,y,Math.max(.1,r),0,Math.PI*2);c.fillStyle=color;c.fill()};
const v8Line=(c,x1,y1,x2,y2,color,wide=2)=>{c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.strokeStyle=color;c.lineWidth=wide;c.stroke()};
const v8Ring=(c,x,y,r,color,wide=3,part=1,start=-Math.PI/2)=>{c.beginPath();c.arc(x,y,Math.max(1,r),start,start+Math.PI*2*part);c.strokeStyle=color;c.lineWidth=wide;c.stroke()};
const v8Glow=(c,x,y,r,col,a=.25)=>{const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,rgba(col,a));g.addColorStop(1,rgba(col,0));c.fillStyle=g;c.fillRect(x-r,y-r,2*r,2*r)};
const v8DrawText=(c,s,key,rect,size,col,idx,thumb,opt={})=>{if(s[key]===undefined)return;textBox(c,s,key,rect,size,col,{index:idx,thumbnail:thumb,align:'center',vertical:'center',lines:2,...opt})};
function v8DrawScene(c,idx,time,canvasObj,opts={}){
 const ratio=opts.forceRatio||state.ratio, d=dim(ratio),w=d.w,h=d.h,m=Math.min(w,h),q=time*Math.PI*2, p=T(),s=state.data[idx],id=SCENES[idx].id,thumb=!!opts.thumb;
 window.__studioTime=time;
 c.setTransform(canvasObj.width/w,0,0,canvasObj.height/h,0,0);c.clearRect(0,0,w,h);
 if(!thumb){activeBoxes=[];lastFit=0;warnings=[]}
 c.save();if(!opts.transparent)baseBackground(c,w,h,time,p,thumb);
 const cx=w*.5,cy=h*.58,progress=enter(time,.02,.60),floating=Math.sin(q)*m*.028,accent=p.main,alt=p.alt;
 // Main visual area is deliberately spacious and scales to all 3 aspect ratios.
 const lower=h>.95*w? h*.36:h*.40;
 switch(id){
 case 'v8_neon_tunnel':{
  v8Glow(c,cx,cy,m*.65,p.main,.19);
  for(let j=15;j>=0;j--){const z=((j/16+time*.36)%1);const sc=Math.pow(z,2.1), ww=w*.06+sc*w*1.17,hh=h*.07+sc*h*1.04;
   c.save();c.globalAlpha=.06+.67*(1-z);c.lineWidth=2+sc*5;c.strokeStyle=j%2?p.main:p.alt;c.strokeRect(cx-ww/2,cy-hh/2,ww,hh);c.restore();}
  for(let j=0;j<28;j++){const a=j/28*Math.PI*2+time*.18,x=cx+Math.cos(a)*w*.49,y=cy+Math.sin(a)*h*.39;v8Line(c,cx,cy,x,y,rgba(j%3?p.alt:p.main,.11),1)}break;
 }
 case 'v8_prism_shards':{
  v8Glow(c,cx,cy,m*.5,p.alt,.19);
  for(let j=0;j<27;j++){const a=j*2.399+time*.12,dist=m*(.09+v8N(j+3)*.42)*progress;
   const x=cx+Math.cos(a)*dist,y=cy+Math.sin(a)*dist*.72;
   c.save();c.translate(x,y);c.rotate(a+time*.7);const sz=m*(.036+v8N(j+1)*.095);c.beginPath();c.moveTo(-sz,sz*.6);c.lineTo(0,-sz);c.lineTo(sz*.9,sz*.7);c.closePath();c.fillStyle=rgba(j%2?p.main:p.alt,.05+v8N(j+4)*.27);c.strokeStyle=rgba(j%2?p.alt:p.main,.35);c.lineWidth=2;c.fill();c.stroke();c.restore();}break;
 }
 case 'v8_fluid_glass':{
  for(let j=0;j<11;j++){let x=w*(.1+.8*v8N(j*3+1))+Math.sin(q+j)*m*.024,y=h*(.33+.49*v8N(j*4+2))+Math.cos(q*.9+j)*m*.023;
   const r=m*(.055+.115*v8N(j+19));v8Glow(c,x,y,r*1.6,j%2?p.main:p.alt,.13);
   const g=c.createRadialGradient(x-r*.4,y-r*.6,3,x,y,r);g.addColorStop(0,'rgba(255,255,255,.28)');g.addColorStop(.25,rgba(j%2?p.main:p.alt,.21));g.addColorStop(1,'rgba(255,255,255,.03)');c.fillStyle=g;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();v8Ring(c,x,y,r,'rgba(255,255,255,.24)',2);}break;
 }
 case 'v8_laser_grid':{
  const horizon=h*.55;v8Glow(c,cx,horizon,m*.48,p.main,.18);
  for(let j=-15;j<=15;j++){const x=cx+j*w*.075;v8Line(c,cx,horizon,x,h,rgba(p.alt,.20),1.5)}
  for(let j=0;j<17;j++){const z=((j/17+time*.58)%1),y=horizon+Math.pow(z,2.25)*(h-horizon);v8Line(c,0,y,w,y,rgba(p.main,.12+z*.38),1+z*3)}
  for(let j=0;j<7;j++){const x=(v8N(j+11)*w+time*w*.7)%w;v8Line(c,x,h*.34,x+m*.09,h*.70,rgba(p.main,.14),3)}break;
 }
 case 'v8_film_countdown':{
  c.save();c.translate(cx,cy);c.rotate(time*2.9);for(let j=0;j<40;j++){let a=j*Math.PI/20, r=m*.29;v8Line(c,Math.cos(a)*r,Math.sin(a)*r,Math.cos(a)*(r+(j%5?11:27)),Math.sin(a)*(r+(j%5?11:27)),rgba(p.main,.28+j%5*.11),j%5?2:5)}c.restore();
  for(let j=0;j<5;j++)v8Ring(c,cx,cy,m*(.16+j*.038),rgba(j%2?p.main:p.alt,.17+j*.02),j===0?9:2,progress,-Math.PI/2+q*.12);
  v8Line(c,cx,cy-m*.39,cx,cy+m*.39,rgba(p.text,.10),2);v8Line(c,cx-m*.39,cy,cx+m*.39,cy,rgba(p.text,.10),2);break;
 }
 case 'v8_shockwave':{
  for(let j=0;j<7;j++){const r=m*(.05+((time*1.4+j/7)%1)*.65),a=(1-((time*1.4+j/7)%1))*.45;v8Ring(c,cx,cy,r,rgba(j%2?p.main:p.hot,a),2+j%2*4)}
  for(let j=0;j<40;j++){const a=j*Math.PI/20+q*.06,R=m*(.17+.39*progress+.04*v8N(j));v8Line(c,cx+Math.cos(a)*m*.18,cy+Math.sin(a)*m*.18,cx+Math.cos(a)*R,cy+Math.sin(a)*R,rgba(j%3?p.main:p.alt,.2+.3*v8N(j)),2+v8N(j+2)*4)}break;
 }
 case 'v8_kinetic_bars':{
  for(let j=0;j<12;j++){const y=h*(.36+j*.042),wave=Math.sin(q+j*.49)*w*.04;rr(c,w*.04+wave,y,w*.92*Math.min(1,progress+j*.08),h*.020,4,j%3?rgba(p.alt,.23):rgba(p.main,.34));}
  for(let j=0;j<4;j++){c.save();c.translate(cx,cy);c.rotate(-.21);rr(c,-w*.49,-m*.24+j*m*.15,w*.98,m*.072,7,rgba(j%2?p.main:p.alt,.14));c.restore();}break;
 }
 case 'v8_iris_reveal':{
  v8Glow(c,cx,cy,m*.47,p.alt,.2);
  for(let j=0;j<10;j++){const a=q*.23+j*Math.PI/5,r=m*.37;c.save();c.translate(cx,cy);c.rotate(a);c.fillStyle=rgba(j%2?p.main:p.alt,.08);c.strokeStyle=rgba(p.main,.31);c.lineWidth=2;c.beginPath();c.moveTo(0,0);c.lineTo(r,-r*.30);c.lineTo(r,r*.23);c.closePath();c.fill();c.stroke();c.restore()}
  for(let j=0;j<5;j++)v8Ring(c,cx,cy,m*(.11+j*.065),rgba(p.alt,.25-j*.032),2+j%2*3,progress,-Math.PI/2+j*.4);break;
 }
 case 'v8_aurora_ribbons':{
  for(let k=0;k<7;k++){c.beginPath();for(let j=0;j<=90;j++){const x=(j/90)*w,y=cy+Math.sin(x/w*7+q*.48+k*.8)*m*.13+(k-3)*m*.055+Math.sin(q+k)*m*.07;j?c.lineTo(x,y):c.moveTo(x,y)}c.strokeStyle=rgba(k%2?p.main:p.alt,.08+k*.032);c.lineWidth=m*(.012+k*.005);c.lineCap='round';c.stroke()}
  for(let j=0;j<50;j++){const x=w*v8N(j+40),y=h*(.33+v8N(j+82)*.43);v8Point(c,x,y,1+v8N(j)*3,rgba(p.text,.12+v8N(j)*.3))}break;
 }
 case 'v8_comet_trails':{
  for(let j=0;j<130;j++){const rr0=m*(.1+.56*v8N(j+1)),a=j*2.399+q*(.20+v8N(j+41)*.32),x=cx+Math.cos(a)*rr0,y=cy+Math.sin(a)*rr0*.68,len=6+65*v8N(j+90);v8Line(c,x,y,x-Math.cos(a+1.4)*len,y-Math.sin(a+1.4)*len,rgba(j%4?p.main:p.alt,.14+v8N(j+31)*.58),1+v8N(j)*3)}break;
 }
 case 'v8_parallax_stack':{
  for(let j=0;j<3;j++){let sc=1-j*.14,x=cx-w*.31+j*w*.075+Math.sin(q+j)*m*.016,y=h*.40+j*m*.075+Math.cos(q+j)*m*.017;rr(c,x,y,w*.60*sc,h*.29*sc,24,rgba(p.panel,.88),rgba(j%2?p.main:p.alt,.58),3);v8Line(c,x+24,y+55,x+w*.46*sc,y+55,rgba(p.alt,.26),2)}break;
 }
 case 'v8_quote_stage':{
  for(let j=0;j<5;j++){c.save();c.translate(cx,h*.27);c.rotate((j-2)*.23+Math.sin(q+j)*.07);const g=c.createLinearGradient(0,0,0,h*.56);g.addColorStop(0,rgba(j%2?p.main:p.alt,.32));g.addColorStop(1,rgba(j%2?p.main:p.alt,0));c.fillStyle=g;c.beginPath();c.moveTo(0,0);c.lineTo(-m*.22,h*.55);c.lineTo(m*.22,h*.55);c.fill();c.restore()}
  rr(c,w*.09,h*.40,w*.82,h*.33,24,rgba(p.panel,.86),rgba(p.main,.32),2);break;
 }
 case 'v8_odometer':{
  const count=6,bw=Math.min(w*.12,150),gap=m*.014,start=cx-(count*bw+(count-1)*gap)/2;
  for(let j=0;j<count;j++){const x=start+j*(bw+gap),y=cy-m*.14+Math.sin(q+j)*m*.015;rr(c,x,y,bw,m*.25,12,rgba(p.panel,.91),rgba(j%2?p.main:p.alt,.5),2);v8Line(c,x+5,y+m*.13,x+bw-5,y+m*.13,rgba(p.text,.25),2)}break;
 }
 case 'v8_radial_meter':{
  for(let j=0;j<6;j++){const r=m*(.18+j*.053);v8Ring(c,cx,cy,r,rgba(p.muted,.20),2);v8Ring(c,cx,cy,r,rgba(j%2?p.main:p.alt,.8),4+(j%2)*2,Math.min(1,progress*(.35+j*.11)),-Math.PI/2-q*.05)}
  for(let j=0;j<60;j++){const a=j*Math.PI/30;v8Line(c,cx+Math.cos(a)*m*.39,cy+Math.sin(a)*m*.39,cx+Math.cos(a)*m*(.40+(j%5===0?.018:.005)),cy+Math.sin(a)*m*(.40+(j%5===0?.018:.005)),rgba(p.text,.35),1.5)}break;
 }
 case 'v8_liquid_level':{
  let bx=cx-w*.26,by=h*.39,bw=w*.52,bh=h*.33;rr(c,bx,by,bw,bh,30,rgba(p.panel,.72),rgba(p.text,.20),3);
  c.save();c.beginPath();c.roundRect(bx+5,by+5,bw-10,bh-10,25);c.clip();const level=bh*progress*.81,wy=by+bh-level;const grad=c.createLinearGradient(0,wy,0,by+bh);grad.addColorStop(0,rgba(p.main,.8));grad.addColorStop(1,rgba(p.alt,.58));c.fillStyle=grad;c.beginPath();c.moveTo(bx,by+bh);for(let j=0;j<=80;j++){let x=bx+bw*j/80,y=wy+Math.sin(j*.22+q*2)*m*.012;c.lineTo(x,y)}c.lineTo(bx+bw,by+bh);c.closePath();c.fill();c.restore();break;
 }
 case 'v8_wave_compare':{
  for(let k=0;k<2;k++){let base=h*(.49+k*.22);c.beginPath();for(let j=0;j<=105;j++){let x=w*.13+j/105*w*.74,y=base+Math.sin(j*.22+q*(k?1.8:1.2))*m*(k?.042:.073)*progress+Math.sin(j*.11-q)*m*.025;j?c.lineTo(x,y):c.moveTo(x,y)}c.lineWidth=5;c.strokeStyle=k?p.alt:p.main;c.shadowBlur=17;c.shadowColor=k?p.alt:p.main;c.stroke();c.shadowBlur=0;v8Line(c,w*.11,base,w*.89,base,rgba(p.text,.10),1)}break;
 }
 case 'v8_sparkline':{
  rr(c,w*.10,h*.42,w*.8,h*.32,18,rgba(p.panel,.65),rgba(p.alt,.20));for(let j=1;j<6;j++)v8Line(c,w*.12,h*(.42+j*.055),w*.88,h*(.42+j*.055),rgba(p.text,.10),1);
  c.beginPath();for(let j=0;j<=85*progress;j++){const f=j/85,x=w*(.13+.74*f),y=h*(.68-.22*(f*f+.14*Math.sin(f*25)+.08*Math.sin(f*39)));j?c.lineTo(x,y):c.moveTo(x,y)}c.strokeStyle=p.main;c.lineWidth=8;c.shadowColor=p.main;c.shadowBlur=18;c.stroke();c.shadowBlur=0;break;
 }
 case 'v8_stack_towers':{
  const heights=[.25,.43,.59];for(let j=0;j<3;j++){const bw=w*.15,x=w*(.26+j*.24),bottom=h*.76,ht=h*heights[j]*progress;
    const col=[p.hot,p.alt,p.main][j];c.fillStyle=rgba(col,.62);c.fillRect(x,bottom-ht,bw,ht);c.fillStyle=rgba(col,.84);c.beginPath();c.moveTo(x,bottom-ht);c.lineTo(x+bw*.32,bottom-ht-bw*.18);c.lineTo(x+bw*1.32,bottom-ht-bw*.18);c.lineTo(x+bw,bottom-ht);c.fill();c.fillStyle=rgba(col,.38);c.beginPath();c.moveTo(x+bw,bottom-ht);c.lineTo(x+bw*1.32,bottom-ht-bw*.18);c.lineTo(x+bw*1.32,bottom-bw*.18);c.lineTo(x+bw,bottom);c.fill();}
  break;
 }
 case 'v8_planet_orbit':{
  v8Glow(c,cx,cy,m*.44,p.alt,.16);for(let j=0;j<5;j++){const rx=m*(.23+j*.070),ry=rx*(.41+j*.03);c.save();c.translate(cx,cy);c.rotate(-.24+j*.13);c.beginPath();c.ellipse(0,0,rx,ry,0,0,Math.PI*2);c.strokeStyle=rgba(j%2?p.main:p.alt,.21+j*.065);c.lineWidth=2+j%2*2;c.stroke();const a=q*(.24+j*.09)+j*1.8;v8Point(c,Math.cos(a)*rx,Math.sin(a)*ry,7+j*2,j%2?p.alt:p.main);c.restore()}break;
 }
 case 'v8_radar_scope':{
  const r=m*.37;for(let j=1;j<=5;j++)v8Ring(c,cx,cy,r*j/5,rgba(p.main,.25),1.5);v8Line(c,cx-r,cy,cx+r,cy,rgba(p.main,.22));v8Line(c,cx,cy-r,cx,cy+r,rgba(p.main,.22));c.save();c.translate(cx,cy);c.rotate(q);const g=c.createConicGradient(-Math.PI*.44,0,0);g.addColorStop(0,rgba(p.main,.65));g.addColorStop(.22,rgba(p.main,0));g.addColorStop(1,rgba(p.main,0));c.fillStyle=g;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.restore();for(let j=0;j<12;j++){const a=j*2.39,dist=r*(.18+.72*v8N(j+31));v8Point(c,cx+Math.cos(a)*dist,cy+Math.sin(a)*dist,3+j%4,rgba(p.alt,.70))}break;
 }
 case 'v8_news_flash':{
  for(let j=0;j<7;j++){const y=h*.40+j*h*.057;rr(c,w*.02,y,w*.96,h*.035,2,j%2?rgba(p.main,.21):rgba(p.alt,.26));}
  rr(c,0,h*.76,w,h*.13,0,p.main);rr(c,0,h*.9,w,h*.045,0,p.alt);rr(c,0,h*.35,w,h*.012,0,p.hot);break;
 }
 case 'v8_reel_stickers':{
  for(let j=0;j<20;j++){let x=w*(.06+.85*v8N(j+1)),y=h*(.34+.48*v8N(j+7));const sc=1+.1*Math.sin(q*2+j),r=m*(.016+.028*v8N(j+4));c.save();c.translate(x,y);c.rotate(j*2.11+q*.17);c.scale(sc,sc);rr(c,-r*1.5,-r,r*3,r*2,8,j%2?p.main:p.alt,rgba(p.text,.65),2);c.restore()}break;
 }
 case 'v8_blueprint':{
  for(let j=0;j<26;j++){v8Line(c,w*.09+j*w*.032,h*.35,w*.09+j*w*.032,h*.75,rgba(p.main,.08),1)}for(let j=0;j<12;j++)v8Line(c,w*.09,h*(.35+j*.036),w*.91,h*(.35+j*.036),rgba(p.main,.08),1);
  for(let j=0;j<3;j++){const x=w*(.17+j*.27),y=h*.5+(1-progress)*h*.15;rr(c,x,y,w*.20,h*.15,10,rgba(p.panel,.85),rgba(p.main,.65),3);if(j<2){v8Line(c,x+w*.20,y+h*.075,x+w*.27,y+h*.075,p.alt,4);v8Point(c,x+w*.27,y+h*.075,5,p.alt)}}break;
 }
 case 'v8_halftone':{
  for(let j=0;j<24;j++)for(let k=0;k<13;k++){let r=m*.0028*(1+4*Math.abs(Math.sin(j*.27+k*.34+q*.22)));v8Point(c,w*(.04+j*.04),h*(.32+k*.041),r,rgba(j%2?p.main:p.alt,.35))}
  for(let j=0;j<3;j++)v8Ring(c,cx,cy,m*(.25+j*.12),rgba(j%2?p.main:p.hot,.45),6,1,-Math.PI/2+q*.10);break;
 }
 }
 // New layouts use independent editable text boxes, maintaining existing typography controls.
 const fontBase=Math.max(32,Math.min(88,w*.065));
 const txt=(key,x,y,bw,bh,size,col,opt)=>v8DrawText(c,s,key,{x,y,w:bw,h:bh},size,col,idx,thumb,opt);
 txt('tag',w*.12,h*.065,w*.76,h*.048,Math.max(16,Math.min(26,w*.019)),p.main,{lines:1});
 txt('title',w*.07,h*.13,w*.86,h*.19,fontBase,p.text,{lines:3,weight:950});
 if(id==='v8_parallax_stack'||id==='v8_blueprint'){
  ['a','b','c'].forEach((k,j)=>txt(k,w*(.17+j*.27),id==='v8_blueprint'?h*.51:h*(.45+j*.08),w*.20,h*.14,Math.min(39,w*.029),j===1?p.main:p.text,{lines:2}));
 }else if(id==='v8_wave_compare'){
  txt('a',w*.10,h*.41,w*.24,h*.055,29,p.main,{lines:1});txt('av',w*.64,h*.41,w*.25,h*.07,42,p.main);
  txt('b',w*.10,h*.63,w*.24,h*.055,29,p.alt,{lines:1});txt('bv',w*.64,h*.63,w*.25,h*.07,42,p.alt);
 }else if(id==='v8_stack_towers'){
  ['a','b','c'].forEach((key,j)=>{const x=w*(.21+j*.24);txt(key,x,h*.78,w*.18,h*.049,Math.min(27,w*.025),p.text,{lines:1});txt(key==='a'?'av':key==='b'?'bv':'cv',x,h*.81,w*.18,h*.055,Math.min(39,w*.031),p.main,{lines:1})});
 }else if(id==='v8_news_flash'){
  txt('value',w*.08,h*.50,w*.84,h*.16,Math.min(130,w*.09),p.text,{lines:2});
  txt('note',w*.03,h*.775,w*.94,h*.09,Math.min(40,w*.026),p.bg,{lines:1});
 }else{
  let y=id==='v8_quote_stage'?h*.47:h*.52,sz=id==='v8_quote_stage'?Math.min(63,w*.048):Math.min(118,w*.085);
  if(id==='v8_kinetic_bars')y=h*.50;
  txt('value',w*.1,y,w*.8,id==='v8_quote_stage'?h*.20:h*.17,sz,p.text,{lines:id==='v8_quote_stage'?3:2,weight:950});
  txt('note',w*.12,h*.84,w*.76,h*.061,Math.min(27,w*.023),p.muted,{lines:2});
 }
 c.restore();
}
function v8Ambient(c,idx,time,canvasObj,opts={}){
 const fx=state.atmosphere||'none';if(fx==='none')return;
 const ratio=opts.forceRatio||state.ratio,d=dim(ratio),w=d.w,h=d.h,p=T(),t=time,st=clamp((state.fxStrength||65)/100),q=t*Math.PI*2;
 c.save();c.setTransform(canvasObj.width/w,0,0,canvasObj.height/h,0,0);
 if(fx==='stardust'){
  for(let j=0;j<100;j++){let x=(v8N(j+101)*w+Math.sin(q+j)*w*.016+w)%w,y=(v8N(j+81)*h+t*h*(.04+v8N(j+93)*.12))%h;v8Point(c,x,y,(1+v8N(j+5)*3)*st,rgba(j%3?p.main:p.alt,(.12+v8N(j+12)*.45)*st))}
 }else if(fx==='light'){
  let x=(t*1.5-.3)*w;const g=c.createLinearGradient(x-130,0,x+130,0);g.addColorStop(0,rgba(p.main,0));g.addColorStop(.48,rgba(p.main,.13*st));g.addColorStop(.5,'rgba(255,255,255,'+(.16*st)+')');g.addColorStop(1,rgba(p.main,0));c.fillStyle=g;c.fillRect(x-130,0,260,h);
 }else if(fx==='film'){
  for(let j=0;j<100;j++){let x=v8N(j*2+201)*w,y=v8N(j*3+202)*h,v=v8N(j+211);v8Point(c,x,y,(.8+v*1.6)*st,'rgba(255,255,255,'+(.035*st)+')')}
  for(let j=0;j<4;j++){let y=((j*.26+t*.14)%1)*h;v8Line(c,0,y,w,y,rgba(p.text,.038*st),1)}
 }else if(fx==='electric'){
  for(let j=0;j<21;j++){const a=j*2.399+q*.29,x=w*(.5+.45*Math.cos(a)),y=h*(.52+.42*Math.sin(a)),len=25+35*v8N(j+72);v8Line(c,x,y,x+len*Math.cos(a+.9),y+len*Math.sin(a+.9),rgba(j%2?p.main:p.alt,.4*st),2)}
 }else if(fx==='scanlines'){
  for(let y=0;y<h;y+=7){v8Line(c,0,y,w,y,rgba(p.text,.045*st),1)}let scan=(t%1)*h;v8Line(c,0,scan,w,scan,rgba(p.main,.6*st),3)
 }else if(fx==='halftone_vox'){
  for(let x=18;x<w;x+=28)for(let y=18;y<h;y+=28){let r=(1.2+Math.sin(x*.015+y*.015+q)*.9)*st;v8Point(c,x,y,r,rgba(p.main,.13*st))}
  for(let j=0;j<90;j++){let gx=v8N(j*3+17)*w,gy=v8N(j*5+31)*h;v8Point(c,gx,gy,1.3*st,rgba('#fff8e7',.07*st))}
 }
 c.restore();
}
// Thumbnail images only render when their cards enter the scrolling library.
const v8Observer=typeof IntersectionObserver!=='undefined'?new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const id=entry.target?.id;const index=Number(id?.replace('thumb-',''));v8Observer.unobserve(entry.target);if(Number.isInteger(index)&&id==='thumb-'+index)renderThumb(index)}},{root:document.querySelector('.library'),rootMargin:'200px 80px'}):null;
function lazySceneThumb(i){const target=$('thumb-'+i);if(!target)return;if(v8Observer)v8Observer.observe(target);else renderThumb(i)}

const v8PreviousRender=renderScene;
renderScene=function(c,idx,time,canvasObj=cv,opts={}){
 const id=SCENES[idx]?.id;const t=clamp(time*state.speed);
 window.__studioTime=t;
 if(V8_IDS.has(id))v8DrawScene(c,idx,t,canvasObj,opts);else v8PreviousRender(c,idx,time,canvasObj,opts);
 v8Ambient(c,idx,t,canvasObj,opts);
};
function v8Number(raw,tm){
 const match=String(raw).match(/^(\D*?)(-?\d[\d,]*(?:\.\d+)?)([\s\S]*)$/);if(!match)return String(raw);
 const number=Number(match[2].replaceAll(',',''));if(!Number.isFinite(number))return String(raw);
 const decimal=(match[2].split('.')[1]||'').length;
 const value=number*enter(tm,.07,.68);
 return match[1]+value.toLocaleString('en-IN',{minimumFractionDigits:decimal,maximumFractionDigits:decimal})+match[3];
}

