async function v8LoadCustomFont(data){
 if(!data||typeof FontFace==='undefined')return;
 const face=new FontFace('Studio Custom',`url(${data})`);
 await face.load();document.fonts.add(face);
 const picker=$('studioFont');if(picker&&!Array.from(picker.options).some(o=>o.value==='Studio Custom')){const o=document.createElement('option');o.value='Studio Custom';o.textContent='My uploaded font';picker.append(o)}
 window.studioTypeface='Studio Custom';picker.value='Studio Custom';state.customFont=data;renderFrame();renderThumb(state.scene);
}
