function v8UpdateControls(){
 if($('motionPreset'))$('motionPreset').value=state.motionPreset||'cinematic';
 if($('textMotion'))$('textMotion').value=state.textMotion||'rise';
 if($('atmosphere'))$('atmosphere').value=state.atmosphere||'none';
 if($('fxStrength')){$('fxStrength').value=state.fxStrength||65;$('fxStrengthValue').textContent=(state.fxStrength||65)+'%'}
 if($('metricAnimation'))$('metricAnimation').checked=state.metricAnimation!==false;
}
const v8OriginalSave=saveProject;
saveProject=function(){
 const obj={format:'your-next-move-motion-studio',version:4,graphicScale:state.graphicScale,ratio:state.ratio,scene:state.scene,theme:state.theme,colors:state.colors,data:state.data,typo:state.typo,durations:state.durations,speed:state.speed,mapZoom:state.mapZoom,mapRegion:state.mapRegion,mapLabels:state.mapLabels,safe:state.safe,showGrid:state.showGrid,bgStyle:state.bgStyle,bgStyles:state.bgStyles,bgImage:state.bgImage,overlay:state.overlay,typeface:window.studioTypeface||'Inter',customFont:state.customFont||null,motionPreset:state.motionPreset,textMotion:state.textMotion,atmosphere:state.atmosphere,fxStrength:state.fxStrength,metricAnimation:state.metricAnimation};
 download(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),'Motion_Studio_Ultra_V8_Project.json');info('Project saved with fonts and effects');
};
const v8OriginalLoad=loadProject;
loadProject=function(file){
 // Keep the V5-V7 project loader, but extend it to restore V8 properties.
 file.text().then(raw=>{const obj=JSON.parse(raw);if(obj.version>=4){state.motionPreset=['cinematic','subtle','energetic'].includes(obj.motionPreset)?obj.motionPreset:'cinematic';state.textMotion=['none','rise','slide','zoom','typewriter','glitch','float'].includes(obj.textMotion)?obj.textMotion:'rise';state.atmosphere=['none','halftone_vox','stardust','light','film','electric','scanlines'].includes(obj.atmosphere)?obj.atmosphere:'none';state.fxStrength=clamp(Number(obj.fxStrength)||65,0,100);state.metricAnimation=obj.metricAnimation!==false;window.studioTypeface=obj.typeface||'Inter';if(obj.customFont){v8LoadCustomFont(obj.customFont).catch(()=>info('Saved font could not be loaded'))}const picker=$('studioFont');if(picker)picker.value=window.studioTypeface;document.fonts.load('700 48px "'+window.studioTypeface+'"','ಕನ್ನಡ Motion Studio').then(()=>renderFrame()).catch(()=>{});v8UpdateControls();}
  v8OriginalLoad(file);setTimeout(()=>v8BuildQuick(),80);
 }).catch(e=>info('Project could not be read: '+e.message));
};
function v8Boot(){
 const bindings=[['motionPreset','motionPreset'],['textMotion','textMotion'],['atmosphere','atmosphere']];
 for(const [id,key] of bindings)$(id)?.addEventListener('change',e=>{state[key]=e.target.value;renderFrame();renderThumb(state.scene)});
 $('customFontFile')?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){info('Choose a font smaller than 5 MB');return}const r=new FileReader();r.onload=()=>v8LoadCustomFont(r.result).then(()=>info('Custom font ready')).catch(err=>info('Could not load this font: '+err.message));r.readAsDataURL(file)});
 $('fxStrength')?.addEventListener('input',e=>{state.fxStrength=Number(e.target.value);$('fxStrengthValue').textContent=state.fxStrength+'%';renderFrame()});
 $('metricAnimation')?.addEventListener('change',e=>{state.metricAnimation=e.target.checked;renderFrame()});
 $('surpriseScene')?.addEventListener('click',()=>{let next=state.scene;for(let k=0;k<7&&next===state.scene;k++)next=Math.floor(Math.random()*SCENES.length);setScene(next);info('Now exploring '+SCENES[next].name)});
 $('randomPalette')?.addEventListener('click',()=>{const next=THEMES[(THEMES.findIndex(x=>x.id===state.theme)+1)%THEMES.length];state.theme=next.id;state.colors=null;colorPicker();renderFrame();sceneList();info('Palette: '+next.name)});
 // One-click scene navigation: / focuses search; Space plays or pauses; arrow keys scrub when preview focused.
 window.addEventListener('keydown',e=>{if((e.key==='/'||e.key==='f')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();$('sceneSearch').focus();$('sceneSearch').select()}});
 // Make every scene thumbnail lazy: large maps no longer block template scrolling.
 v8UpdateControls();v8BuildQuick();
 window.MotionStudio.version='8.0';window.MotionStudio.extraLayouts=V8_LAYOUTS;
 window.MotionStudio.renderScene=renderScene;
 $('saveProject').onclick=saveProject;
 window.MotionStudio.saveProject=saveProject;
 window.MotionStudio.loadProject=loadProject;
 window.MotionStudio.setScene=setScene;
 info('Ready • '+SCENES.length+' editable motion layouts');
}
v8Boot();

